import{_ as t,C as e,o as l,c as h,j as i,E as s,a as r,a3 as o}from"./chunks/framework.C6R8kWFE.js";const S=JSON.parse(`{"title":"18-dars (Mentor). O'yin interfeysini prototiplash (2-qism): O'yin stsenariysiga mos interfeys sxemasini chizish","description":"","frontmatter":{"title":"18-dars (Mentor). O'yin interfeysini prototiplash (2-qism): O'yin stsenariysiga mos interfeys sxemasini chizish","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":6,"link":"/mentor/9-sinf-game/hafta-06/"},"g":18,"title":"O'yin interfeysini prototiplash (2-qism): O'yin stsenariysiga mos interfeys sxemasini chizish","lead":"O'yin interfeysi bitta ekran emas, ekranlar tizimi. Bugun stsenariydan kerakli ekranlarni ajratib, ularning xaritasini va sxemasini chizamiz.","slide":"/slaydlar/9-sinf-game/hafta-06/dars-3.html","test":"/slaydlar/9-sinf-game/hafta-06/dars-3-test.html","student_link":"/9-sinf-game/hafta-06/dars-3","tabs":[{"g":16,"link":"/mentor/9-sinf-game/hafta-06/dars-1","current":false},{"g":17,"link":"/mentor/9-sinf-game/hafta-06/dars-2","current":false},{"g":18,"link":"/mentor/9-sinf-game/hafta-06/dars-3","current":true}],"prev":{"g":17,"title":"O'yin interfeysini prototiplash (1-qism): Wireframe, Mockup va Prototype bosqichlari","link":"/mentor/9-sinf-game/hafta-06/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-06/dars-3.md","filePath":"mentor/9-sinf-game/hafta-06/dars-3.md"}`),g={name:"mentor/9-sinf-game/hafta-06/dars-3.md"},m={class:"blk"},p={id:"dars-rejasi",tabindex:"-1"},y={class:"blk"},d={id:"mentor-konspekti",tabindex:"-1"},u={class:"blk"},k={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},q={class:"blk"},b={id:"tezkor-nazorat-savollari",tabindex:"-1"},c={class:"blk"},f={id:"uyga-vazifa",tabindex:"-1"};function v(x,a,z,_,P,T){const n=e("Icon");return l(),h("div",null,[i("div",m,[i("h2",p,[s(n,{name:"file-text"}),a[0]||(a[0]=r(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=o("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga o&#39;yin stsenariysidan kerakli interfeys ekranlarini ajratib olishni, ekranlar o&#39;rtasidagi o&#39;tishlarni sxemada (ekranlar xaritasi) ko&#39;rsatishni, har ekran uchun wireframe tuzishni va uni Photoshop&#39;da guruhlangan qatlamlar bilan chizishni o&#39;rgatish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar o&#39;yin stsenariysidan kamida 5 ta kerakli ekranni aniqlaydi; ekranlar xaritasini (qaysi tugma qaysi ekranga olib boradi) chizadi; har bir ekranda ortga qaytish yo&#39;li borligini tekshiradi; har ekran uchun element ro&#39;yxatini (tugma, HUD, matn) tuzadi; photoshop&#39;da ekranlar sxemasini guruhlangan qatlamlar bilan tayyorlaydi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>17-dars: Wireframe, Mockup, Prototype: 10 daqiqa</li><li>Stsenariydan ekranlar ro&#39;yxati: 10 daqiqa</li><li>Ekranlar xaritasi (screen flow): 20 daqiqa</li><li>Har ekran wireframe&#39;i: 15 daqiqa</li><li>Amaliyot: Photoshop&#39;da sxema: 25 daqiqa</li></ul></li></ul><blockquote><p>Manba: o&#39;quv dasturi — «O&#39;yin interfeysini prototiplash» moduli («o&#39;yin jarayoniga mos interfeys elementlari (tugmalar, menyular, HUD); Photoshopda prototip yaratish jarayoni»; «Tugmalar va menyularni joylashtirib, ekran maketini tayyorlashni o&#39;rganadi»); o&#39;quv qo&#39;llanma — 2.5-bo&#39;lim va Photoshop&#39;da UI yaratish bosqichlari (struktura, foydalanuvchi ssenariylari — User Journey Mapping, past darajali maketlar); uslubiy ko&#39;rsatma — 1.5-mashg&#39;ulot (1920×1080 hujjat, Rectangle Tool, Text Tool, ikonkalar, Ctrl+G). Misol stsenariy («Robo-changyutkich») uslubiy ko&#39;rsatmadagi xona/tanga mashqiga tayanadi.</p></blockquote><hr>",3))]),i("div",y,[i("h2",d,[s(n,{name:"file-text"}),a[3]||(a[3]=r(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=o(`<h3 id="_1-o-yin-stsenariysidan-ekranlar-ro-yxati" tabindex="-1">1. O&#39;yin stsenariysidan ekranlar ro&#39;yxati <a class="header-anchor" href="#_1-o-yin-stsenariysidan-ekranlar-ro-yxati" aria-label="Permalink to &quot;1. O&#39;yin stsenariysidan ekranlar ro&#39;yxati&quot;">​</a></h3><p>Interfeys o&#39;yin <strong>stsenariysiga</strong> (o&#39;yinchi nima qiladi, qanday boshlanadi va tugaydi) mos bo&#39;lishi kerak. Birinchi qadam — stsenariyni o&#39;qib, <strong>qaysi ekranlar kerakligini</strong> aniqlash. Qo&#39;llanma Photoshop&#39;da UI yaratish bosqichlarini sanaydi: tuzilmani aniqlash, foydalanuvchi ssenariylarini loyihalash (User Journey Mapping), keyin past darajali maket. <strong>Namunaviy stsenariy:</strong> «Robo-changyutkich xonani aylanib, tanga yig&#39;adi va to&#39;siqlardan qochadi; sog&#39;lig&#39;i tugasa o&#39;yin tugaydi.» Undan ekranlar: 1) <strong>Bosh menyu</strong> (START, Sozlamalar, Chiqish); 2) <strong>O&#39;yin ekrani</strong> (HUD: health bar, tangalar, mini-xarita); 3) <strong>Pauza menyusi</strong> (Davom etish, Sozlamalar, Bosh menyuga); 4) <strong>Sozlamalar</strong> (tovush, grafika, boshqaruv, Ortga); 5) <strong>O&#39;yin tugadi</strong> (natija: yig&#39;ilgan tangalar, Qayta boshlash, Bosh menyuga). Har ekranga nom va qisqa vazifa yoziladi.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>1. Bosh menyu     - START, Sozlamalar, Chiqish</span></span>
<span class="line"><span>2. O&#39;yin ekrani   - HUD: health bar, tangalar, mini-xarita</span></span>
<span class="line"><span>3. Pauza menyusi  - Davom etish, Sozlamalar, Bosh menyuga</span></span>
<span class="line"><span>4. Sozlamalar     - Tovush, Grafika, Boshqaruv, Ortga</span></span>
<span class="line"><span>5. O&#39;yin tugadi   - Natija, Qayta boshlash, Bosh menyuga</span></span></code></pre></div><blockquote><p>Professional maslahat: Savol: «o&#39;yinchi bu lahzada nimani ko&#39;rishi va nimani bosishi kerak?» — har javob bitta ekran elementi bo&#39;ladi.</p></blockquote><h3 id="_2-ekranlar-xaritasi-qaysi-tugma-qayerga-olib-boradi" tabindex="-1">2. Ekranlar xaritasi: qaysi tugma qayerga olib boradi <a class="header-anchor" href="#_2-ekranlar-xaritasi-qaysi-tugma-qayerga-olib-boradi" aria-label="Permalink to &quot;2. Ekranlar xaritasi: qaysi tugma qayerga olib boradi&quot;">​</a></h3><p><strong>Ekranlar xaritasi</strong> (screen flow) — ekranlarni to&#39;rtburchak, o&#39;tishlarni strelka sifatida ko&#39;rsatadigan sxema; har strelkaga o&#39;tishni keltirib chiqaruvchi harakat (tugma) yoziladi. Xaritadan <strong>navigatsiya xatolari</strong> darrov ko&#39;rinadi. Tekshirish qoidalari: 1) har ekrandan <strong>ortga yo&#39;l</strong> bo&#39;lsin (Sozlamalar&#39;da «Ortga» bo&#39;lmasa, o&#39;yinchi chiqa olmaydi); 2) <strong>boshi va oxiri</strong> aniq: o&#39;yin qayerdan boshlanadi (Bosh menyu) va qayerda tugaydi (O&#39;yin tugadi → Bosh menyu yoki Qayta boshlash); 3) <strong>yopiq tuzoq</strong> yo&#39;q (hech qayerga olib bormaydigan ekran); 4) Pauza va Sozlamalar <strong>ikki joydan</strong> ochilishi mumkin — «Ortga» tugmasi qaysi ekranga qaytarishini aniqlang. Xaritani avval qog&#39;ozda chizing, keyin Photoshop&#39;da qutilar va strelkalar bilan qayta yig&#39;ing (Rectangle Tool, Pen Tool/Line).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Bosh menyu --START--&gt; O&#39;yin ekrani --Esc--&gt; Pauza menyusi</span></span>
<span class="line"><span>    |   ^                  |   ^                |      |</span></span>
<span class="line"><span>    |   |                  |   +--Davom etish---+      |</span></span>
<span class="line"><span>    |   +---Bosh menyuga---+--------------------------+</span></span>
<span class="line"><span>    |                      |</span></span>
<span class="line"><span>Sozlamalar            sog&#39;liq = 0</span></span>
<span class="line"><span>    |  ^                   |</span></span>
<span class="line"><span>  Ortga                    v</span></span>
<span class="line"><span>                       O&#39;yin tugadi --Qayta boshlash--&gt; O&#39;yin ekrani</span></span></code></pre></div><blockquote><p>Professional maslahat: Bu sxema soddalashtirilgan: asosiy yo&#39;llar ko&#39;rsatilgan. Sozlamalar Pauza menyusidan ham ochilsa, «Ortga» o&#39;sha menyuga qaytaradi.</p></blockquote><h3 id="_3-har-ekran-wireframe-i-va-photoshop-da-yig-ish" tabindex="-1">3. Har ekran wireframe&#39;i va Photoshop&#39;da yig&#39;ish <a class="header-anchor" href="#_3-har-ekran-wireframe-i-va-photoshop-da-yig-ish" aria-label="Permalink to &quot;3. Har ekran wireframe&#39;i va Photoshop&#39;da yig&#39;ish&quot;">​</a></h3><p>Har ekran uchun <strong>elementlar ro&#39;yxati</strong> va <strong>wireframe</strong> tuziladi. Photoshop&#39;da (uslubiy ko&#39;rsatma 1.5-mashg&#39;ulot asosida): yangi hujjat <strong>1920×1080 px</strong>, RGB; <strong>Rectangle Tool</strong> bilan kulrang qutilar (tugma, panel), <strong>Text Tool</strong> bilan yorliqlar («START», «Sozlamalar»), o&#39;tgan darslardagi ikonkalar (tanga, yurak) o&#39;z joylariga; har ekran elementlari <strong>Ctrl + G</strong> bilan guruhlanadi va ekran nomi beriladi: «1 Bosh menyu», «2 O&#39;yin», «3 Pauza», «4 Sozlamalar», «5 Tugadi». Bir hujjatda ekranlarni yonma-yon qo&#39;yish yoki har ekranni alohida hujjatda saqlash mumkin. Qoidalar: bir xil tugma — bir xil o&#39;lcham va joy; muhim tugma (START, Davom etish) aniq ajralib turadi; HUD 16-darsdagi joylashuvga mos. Bu hali <strong>wireframe</strong> — rang va bezak keyingi dars (19) da, to&#39;liq prototipni yig&#39;ishda qo&#39;shiladi.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>+------------------------------+</span></span>
<span class="line"><span>|        PAUZA                 |</span></span>
<span class="line"><span>|                              |</span></span>
<span class="line"><span>|     [ DAVOM ETISH ]          |</span></span>
<span class="line"><span>|     [ SOZLAMALAR  ]         |</span></span>
<span class="line"><span>|     [ BOSH MENYUGA ]         |</span></span>
<span class="line"><span>|                              |</span></span>
<span class="line"><span>+------------------------------+</span></span>
<span class="line"><span>Guruh: &quot;3 Pauza&quot;</span></span>
<span class="line"><span>  Matn: PAUZA</span></span>
<span class="line"><span>  Tugma x3 (bir xil o&#39;lcham)</span></span></code></pre></div><blockquote><p>Professional maslahat: Eng ko&#39;p kerak bo&#39;ladigan tugma («Davom etish») tepada turadi. Bir ekrandagi tugmalar bir xil o&#39;lcham va oraliqda bo&#39;lsin.</p></blockquote><hr>`,13))]),i("div",u,[i("h2",k,[s(n,{name:"file-text"}),a[6]||(a[6]=r(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=o('<h3 id="_1-topshiriq-ekranlar-ro-yxati-oson" tabindex="-1">1-topshiriq. Ekranlar ro&#39;yxati (oson) <a class="header-anchor" href="#_1-topshiriq-ekranlar-ro-yxati-oson" aria-label="Permalink to &quot;1-topshiriq. Ekranlar ro&#39;yxati (oson)&quot;">​</a></h3><p>Namunaviy stsenariydan 5 ta ekranni yozing.</p><p><strong>Bajarish tartibi:</strong> Bosh menyu; O&#39;yin ekrani (HUD); Pauza menyusi; Sozlamalar; O&#39;yin tugadi.</p><h3 id="_2-topshiriq-o-yin-ekrani-elementlari-oson" tabindex="-1">2-topshiriq. O&#39;yin ekrani elementlari (oson) <a class="header-anchor" href="#_2-topshiriq-o-yin-ekrani-elementlari-oson" aria-label="Permalink to &quot;2-topshiriq. O&#39;yin ekrani elementlari (oson)&quot;">​</a></h3><p>O&#39;yin ekranida qaysi elementlar bo&#39;lishi kerak?</p><p><strong>Bajarish tartibi:</strong> Health bar (chap yuqori), tangalar (o&#39;ng yuqori), mini-xarita (o&#39;ng pastki), Pauza tugmasi.</p><h3 id="_3-topshiriq-o-tishlar-o-rta" tabindex="-1">3-topshiriq. O&#39;tishlar (o&#39;rta) <a class="header-anchor" href="#_3-topshiriq-o-tishlar-o-rta" aria-label="Permalink to &quot;3-topshiriq. O&#39;tishlar (o&#39;rta)&quot;">​</a></h3><p>«Bosh menyu» dan qaysi ekranlarga o&#39;tish mumkin? Qaysi tugma bilan?</p><p><strong>Bajarish tartibi:</strong> START → O&#39;yin ekrani; Sozlamalar → Sozlamalar ekrani; Chiqish → o&#39;yindan chiqish.</p><h3 id="_4-topshiriq-xatoni-toping-o-rta" tabindex="-1">4-topshiriq. Xatoni toping (o&#39;rta) <a class="header-anchor" href="#_4-topshiriq-xatoni-toping-o-rta" aria-label="Permalink to &quot;4-topshiriq. Xatoni toping (o&#39;rta)&quot;">​</a></h3><p>«Sozlamalar» ekranida faqat Tovush va Grafika bor. Navigatsiya xatosini toping.</p><p><strong>Bajarish tartibi:</strong> O&#39;yinchi ekrandan chiqa olmaydi. Yechim — «Ortga» tugmasini qo&#39;shish; u kelgan ekranga (Bosh menyu yoki Pauza) qaytaradi.</p><h3 id="_5-topshiriq-ekranlar-xaritasi-qiyin" tabindex="-1">5-topshiriq. Ekranlar xaritasi (qiyin) <a class="header-anchor" href="#_5-topshiriq-ekranlar-xaritasi-qiyin" aria-label="Permalink to &quot;5-topshiriq. Ekranlar xaritasi (qiyin)&quot;">​</a></h3><p>5 ekran uchun xaritani chizing; har strelkaga tugma nomini yozing; ortga yo&#39;llarni tekshiring.</p><p><strong>Bajarish tartibi:</strong> Bosh menyu —START→ O&#39;yin; O&#39;yin —Pauza→ Pauza menyusi —Davom etish→ O&#39;yin; Pauza —Bosh menyuga→ Bosh menyu; O&#39;yin —sog&#39;liq 0→ O&#39;yin tugadi —Qayta boshlash→ O&#39;yin; Bosh menyu va Pauza —Sozlamalar→ Sozlamalar —Ortga→ oldingi ekran.</p><h3 id="_6-topshiriq-photoshop-sxema-bonus" tabindex="-1">6-topshiriq. Photoshop sxema (bonus) <a class="header-anchor" href="#_6-topshiriq-photoshop-sxema-bonus" aria-label="Permalink to &quot;6-topshiriq. Photoshop sxema (bonus)&quot;">​</a></h3><p>Pauza menyusi wireframe&#39;ini 1920×1080 px hujjatda chizing va «3 Pauza» guruhiga soling.</p><p><strong>Bajarish tartibi:</strong> Rectangle Tool bilan 3 ta bir xil kulrang tugma (Davom etish, Sozlamalar, Bosh menyuga), Text Tool bilan sarlavha «PAUZA»; Shift bilan tanlab Ctrl + G; guruhni «3 Pauza» deb nomlang; PNG eksport.</p><hr>',19))]),i("div",q,[i("h2",b,[s(n,{name:"file-text"}),a[9]||(a[9]=r(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=o("<ol><li>Ekranlar ro&#39;yxati nimaga asoslanadi? <ul><li><em>Javob:</em> O&#39;yin stsenariysiga.</li></ul></li><li>Ekranlar xaritasi nima? <ul><li><em>Javob:</em> Ekranlar va ular orasidagi o&#39;tishlar sxemasi.</li></ul></li><li>Har ekranda nima bo&#39;lishi shart? <ul><li><em>Javob:</em> Ortga yoki chiqish yo&#39;li.</li></ul></li><li>Namunaviy stsenariydan 3 ta ekran ayting. <ul><li><em>Javob:</em> Bosh menyu, O&#39;yin ekrani, Pauza, Sozlamalar, O&#39;yin tugadi.</li></ul></li><li>Photoshop&#39;da ekran elementlari qanday tartiblanadi? <ul><li><em>Javob:</em> Ctrl + G bilan guruhlab, nom beriladi.</li></ul></li></ol><hr>",2))]),i("div",c,[i("h2",f,[s(n,{name:"house"}),a[12]||(a[12]=r(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("ol",null,[i("li",null,"O'z o'yiningiz stsenariysini 3–4 gapda yozing."),i("li",null,"Stsenariydan kamida 5 ta ekranni ajrating va har biriga 3–4 ta element yozing."),i("li",null,"Ekranlar xaritasini qog'ozda chizing; har strelkaga tugma nomini yozing; ortga yo'llarni tekshiring."),i("li",null,"Ikki ekranning wireframe'ini Photoshop'da (1920×1080 px) chizing, har birini guruhlab nom bering."),i("li",null,"Xaritada chiqishsiz ekran (tuzoq) yo'qligini tekshirib, natijani 2 jumlada yozing.")],-1))])])}const j=t(g,[["render",v]]);export{S as __pageData,j as default};
